/**
 * Weather data subscription tier routes — closes backend#400.
 *
 * Exposes tier definitions (free/pro/enterprise mapped to existing
 * RATE_LIMIT_TIERS), an upgrade endpoint, and a usage dashboard.
 * Tier enforcement middleware is also exported for use on export routes.
 */

import express from 'express';
import { authenticateJWT } from '../middleware/auth.js';
// error-response.js is CJS. Import the .cjs shim (generated by copy-build-assets.mjs)
// so that Node 20 can load it via ESM default import. The .cjs file exists only
// post-build in dist/; suppress the pre-build type-resolution error.
import _errRespModule from '../utils/error-response.js';
const createErrorResponse = (_errRespModule as any).createErrorResponse as (
  message: string,
  code?: string,
  extras?: Record<string, unknown>,
) => object;
import { RATE_LIMIT_TIERS } from '../../shared/schema-api-keys.js';

type DbExecutor = {
  execute: (sql: string, params?: unknown[]) => Promise<{ rows: Record<string, unknown>[] }>;
};

function defaultDb(): DbExecutor {
  let cachedExecuteQuery: ((sql: string, params?: unknown[]) => Promise<{ rows: Record<string, unknown>[] }>) | null =
    null;
  return {
    execute: async (sql: string, params?: unknown[]) => {
      if (!cachedExecuteQuery) {
        const mod = await import('../../database/index.js');
        cachedExecuteQuery = mod.executeQuery;
      }
      return cachedExecuteQuery!(sql, params);
    },
  };
}

// Tier definitions — maps issue#400 names to existing RATE_LIMIT_TIERS values
const PLANS = [
  {
    name: 'free',
    internalTier: RATE_LIMIT_TIERS.BASIC,
    rate_limit_per_hour: 100,
    data_access: ['Last 24h', 'Single station'],
    price_wrf_monthly: 0,
    description: 'Free tier for testnet onboarding',
  },
  {
    name: 'pro',
    internalTier: RATE_LIMIT_TIERS.STANDARD,
    rate_limit_per_hour: 2000,
    data_access: ['90-day history', 'Regional queries', 'CSV export'],
    price_wrf_monthly: 500,
    description: 'Pro tier for serious operators',
  },
  {
    name: 'enterprise',
    internalTier: RATE_LIMIT_TIERS.ENTERPRISE,
    rate_limit_per_hour: null, // unlimited
    data_access: ['Full history', 'Bulk export', 'Streaming WebSocket'],
    price_wrf_monthly: null, // custom
    description: 'Enterprise tier — contact us for pricing',
  },
] as const;

type PlanName = 'free' | 'pro' | 'enterprise';

// In-memory hourly rate-limit counters keyed by apiKeyId + hour
const rateLimitCounters = new Map<string, { count: number; hour: number }>();

function checkHourlyRateLimit(apiKeyId: string, limitPerHour: number | null): boolean {
  if (limitPerHour === null) return true; // unlimited
  const now = new Date();
  const hour = now.getFullYear() * 100000 + (now.getMonth() + 1) * 1000 + now.getDate() * 24 + now.getHours();
  const key = `${apiKeyId}:${hour}`;
  const entry = rateLimitCounters.get(key) ?? { count: 0, hour };
  entry.count += 1;
  rateLimitCounters.set(key, entry);
  return entry.count <= limitPerHour;
}

// Exported middleware — attach to export / streaming routes that need tier gating
export function requireTier(minPlan: PlanName) {
  const planIndex = (n: PlanName) => PLANS.findIndex(p => p.name === n);
  return async (req: express.Request, res: express.Response, next: express.NextFunction) => {
    const db = defaultDb();
    // Pull the API key from the X-API-Key header (api-key-auth sets req.apiKey, fall back to header)
    const apiKey = (req as any).apiKey?.id ?? null;
    if (!apiKey) {
      // No key → free tier
      if (planIndex(minPlan) > 0) {
        return res.status(402).json({
          ...createErrorResponse(
            'Subscription required',
            'SUBSCRIPTION_REQUIRED'
          ),
          upgradeUrl: '/api/subscription/plans',
        });
      }
      return next();
    }
    const result = await db.execute(
      `SELECT rate_limit_tier FROM api_keys WHERE id = $1 AND is_active = true LIMIT 1`,
      [apiKey]
    );
    if (!result.rows.length) {
      return res
        .status(401)
        .json(createErrorResponse('API key not found', 'API_KEY_NOT_FOUND'));
    }
    const tier = String(result.rows[0].rate_limit_tier ?? RATE_LIMIT_TIERS.BASIC);
    const plan = PLANS.find(p => p.internalTier === tier) ?? PLANS[0];
    if (planIndex(plan.name) < planIndex(minPlan)) {
      return res.status(402).json({
        ...createErrorResponse(
          `This endpoint requires the '${minPlan}' plan or higher`,
          'UPGRADE_REQUIRED'
        ),
        currentPlan: plan.name,
        upgradeUrl: '/api/subscription/plans',
      });
    }
    if (!checkHourlyRateLimit(apiKey, plan.rate_limit_per_hour)) {
      return res
        .status(429)
        .json(
          createErrorResponse(
            'Hourly rate limit exceeded for your subscription tier',
            'RATE_LIMIT_EXCEEDED'
          )
        );
    }
    next();
  };
}

export function createSubscriptionRouter(db?: DbExecutor): express.Router {
  const router = express.Router();
  const executor = db ?? defaultDb();

  // GET /api/subscription/plans — public, no auth needed
  router.get('/plans', (_req, res) => {
    res.json({
      success: true,
      plans: PLANS.map(p => ({
        name: p.name,
        rate_limit_per_hour: p.rate_limit_per_hour,
        data_access: p.data_access,
        price_wrf_monthly: p.price_wrf_monthly,
        description: p.description,
      })),
    });
  });

  // Remaining endpoints require auth
  router.use(authenticateJWT);

  // POST /api/subscription/upgrade — update caller's API key tier
  router.post('/upgrade', async (req, res) => {
    const { tier, paymentTxHash } = req.body ?? {};
    const plan = PLANS.find(p => p.name === (tier as string));
    if (!plan) {
      return res.status(400).json(
        createErrorResponse(
          `tier must be one of: ${PLANS.map(p => p.name).join(', ')}`,
          'INVALID_TIER'
        )
      );
    }
    if (plan.name !== 'free' && !paymentTxHash) {
      return res
        .status(400)
        .json(
          createErrorResponse(
            'paymentTxHash is required for paid tiers',
            'MISSING_PAYMENT_TX_HASH'
          )
        );
    }

    const userId = (req as any).user?.id ?? (req as any).user?.userId;
    if (!userId) {
      return res
        .status(401)
        .json(
          createErrorResponse('User ID not found in token', 'USER_ID_NOT_FOUND')
        );
    }

    try {
      // Update the most-recently-used active key for this user
      const result = await executor.execute(
        `UPDATE api_keys SET rate_limit_tier = $1, updated_at = now()
         WHERE user_id = $2 AND is_active = true
         ORDER BY last_used_at DESC NULLS LAST
         LIMIT 1
         RETURNING id, rate_limit_tier`,
        [plan.internalTier, userId]
      );
      if (!result.rows.length) {
        return res
          .status(404)
          .json(
            createErrorResponse(
              'No active API key found for this user',
              'API_KEY_NOT_FOUND'
            )
          );
      }
      return res.json({
        success: true,
        plan: plan.name,
        internalTier: plan.internalTier,
        apiKeyId: result.rows[0].id,
      });
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Database error';
      return res.status(500).json(createErrorResponse(msg, 'DATABASE_ERROR'));
    }
  });

  // GET /api/subscription/usage — current tier + usage stats
  router.get('/usage', async (req, res) => {
    const userId = (req as any).user?.id ?? (req as any).user?.userId;
    if (!userId) {
      return res
        .status(401)
        .json(
          createErrorResponse('User ID not found in token', 'USER_ID_NOT_FOUND')
        );
    }

    try {
      const keyResult = await executor.execute(
        `SELECT id, rate_limit_tier, daily_request_limit, monthly_request_limit, last_used_at
         FROM api_keys WHERE user_id = $1 AND is_active = true
         ORDER BY last_used_at DESC NULLS LAST LIMIT 1`,
        [userId]
      );
      if (!keyResult.rows.length) {
        return res
          .status(404)
          .json(
            createErrorResponse('No active API key found', 'API_KEY_NOT_FOUND')
          );
      }
      const key = keyResult.rows[0];
      const internalTier = String(key.rate_limit_tier ?? RATE_LIMIT_TIERS.BASIC);
      const plan = PLANS.find(p => p.internalTier === internalTier) ?? PLANS[0];

      // Usage in current day
      const usageResult = await executor.execute(
        `SELECT COUNT(*) as requests_today
         FROM api_key_usage
         WHERE api_key_id = $1 AND created_at >= date_trunc('day', now())`,
        [key.id]
      );
      const requestsToday = Number(usageResult.rows[0]?.requests_today ?? 0);
      const dailyLimit = Number(key.daily_request_limit ?? 1000);
      const nextResetAt = new Date();
      nextResetAt.setUTCHours(24, 0, 0, 0);

      return res.json({
        success: true,
        plan: plan.name,
        rate_limit_per_hour: plan.rate_limit_per_hour,
        requests_today: requestsToday,
        daily_limit: dailyLimit,
        next_reset_at: nextResetAt.toISOString(),
        last_used_at: key.last_used_at ?? null,
      });
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Database error';
      return res.status(500).json(createErrorResponse(msg, 'DATABASE_ERROR'));
    }
  });

  return router;
}

export default createSubscriptionRouter();
